sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        // Get the case_id from the path parameter
        var caseId = request.pathParams.case_id;

        // Validate case_id
        if (!caseId) {
            response.setStatus(400);
            response.setBody({
                "error": "Case ID is required",
                "message": "Please provide a case ID in the URL path"
            });
            return;
        }


        var incidentGr = new GlideRecord('incident');
        incidentGr.addQuery('number', caseId);
        incidentGr.query();

        if (!incidentGr.next()) {
            response.setStatus(404);
            response.setBody({
                "error": "Incident not found",
                "message": "No incident found with number: " + caseId
            });
            return;
        }

        // Build response object
        var result = {
            "number": incidentGr.getValue('number'),
            "state": incidentGr.getValue('state'),
            "state_label": incidentGr.getDisplayValue('state'),
            "short_description": incidentGr.getValue('short_description'),
            "description": incidentGr.getValue('description'),
            "priority": incidentGr.getValue('priority'),
            "priority_label": incidentGr.getDisplayValue('priority'),
            "urgency": incidentGr.getValue('urgency'),
            "urgency_label": incidentGr.getDisplayValue('urgency'),
            "impact": incidentGr.getValue('impact'),
            "impact_label": incidentGr.getDisplayValue('impact'),
            "opened_at": incidentGr.getValue('opened_at'),
            "updated_at": incidentGr.getValue('sys_updated_on'),
            "resolved_at": incidentGr.getValue('resolved_at'),
            "close_code": incidentGr.getValue('close_code'),
            "close_notes": incidentGr.getValue('close_notes'),
            "category": incidentGr.getValue('category'),
            "category_label": incidentGr.getDisplayValue('category'),
            "subcategory": incidentGr.getValue('subcategory'),
            "subcategory_label": incidentGr.getDisplayValue('subcategory')
        };

        // Get assigned to information
        if (incidentGr.getValue('assigned_to')) {
            var assignedToGr = new GlideRecord('sys_user');
            if (assignedToGr.get(incidentGr.getValue('assigned_to'))) {
                result.assigned_to = {
                    "value": assignedToGr.getUniqueValue(),
                    "display_value": assignedToGr.getDisplayValue('name')
                };
            }
        }

        // Return success response
        response.setStatus(200);
        response.setBody({
            "result": result
        });

    } catch (e) {
        // Handle errors
        response.setStatus(500);
        response.setBody({
            "error": "Internal server error",
            "message": e.getMessage()
        });
    }
})(request, response);
